"""Oracle captures are generated by ILASP; these tests need no ILASP binary."""

import json
from pathlib import Path
import subprocess
import warnings

import clingo
import pytest

from tools.ilasp.standalone import compile_task, expand_metarule, generate, parse_task, read_task
from tools.ilasp.standalone.__main__ import main
from tools.ilasp.standalone.generator import Options
from tools.ilasp.standalone.task import statements
from tools.ilasp.validate_standalone import EXTENSION_FIXTURE, FIXTURE, weighted_rules

CASES = [case for path in (FIXTURE, EXTENSION_FIXTURE)
         for case in json.loads(path.read_text(encoding="utf-8"))["cases"]]


@pytest.mark.parametrize("case", CASES, ids=lambda case: case["name"])
def test_exact_weighted_space_matches_ilasp_441(case):
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", message="unknown constraint in mode declaration")
        entries = generate(parse_task(case["source"]), Options(**case["options"]))
    assert {(e.cost, e.rule) for e in entries} == weighted_rules(case["output"])
    assert entries == tuple(sorted(set(entries)))


def test_generation_cannot_access_the_executable_or_start_a_process(monkeypatch):
    original_open = Path.open

    def guarded_open(path, *args, **kwargs):
        assert path.name.lower() not in {"ilasp", "ilasp.exe"}
        return original_open(path, *args, **kwargs)

    def forbidden(*args, **kwargs):
        pytest.fail("independent generation attempted to launch a subprocess")

    monkeypatch.setattr(Path, "open", guarded_open)
    monkeypatch.setattr(subprocess, "Popen", forbidden)
    case = next(c for c in CASES if c["name"] == "coin")
    assert len(generate(parse_task(case["source"]))) == 59


def test_background_examples_and_pylasp_do_not_change_static_generation():
    base = "#maxv(0). #modeh(p)."
    task = parse_task(base + '''
        q. #pos(e@5, {p}, {}, {not_p :- not p.}).
        #neg({}, {p}). #brave_ordering(e,f,<).
        #ilasp_script
        raise RuntimeError("must not execute")
        #end.
    ''')
    assert generate(task) == generate(parse_task(base))


@pytest.mark.parametrize("marker", ["#ilasp_script", "#script (python)"])
def test_both_script_forms_are_skipped_without_execution(marker):
    task = parse_task(f'''{marker}
        raise RuntimeError("periods... and #modeh(fake). are script data")
        #end.
        #maxv(0). #modeh(p).
    ''')
    assert [str(entry) for entry in generate(task)] == ["1 ~ p."]


def test_unknown_mode_options_warn_and_remain_available_to_custom_bias():
    with pytest.warns(UserWarning, match='unknown constraint.*custom'):
        task = parse_task('#maxv(0). #modeh(p,(custom)). #bias(":- not constraint(0,custom).").')
    assert "constraint(0, custom)." in compile_task(task)
    assert [str(entry) for entry in generate(task)] == ["1 ~ p."]


def test_script_markers_inside_comments_and_strings_are_data():
    task = parse_task('''%*
        #ilasp_script
        *%
        #maxv(0). #modeh(p).
        %*
        #end.
        *%
        #modeh(q). #bias("attribute(\\\"#ilasp_script\\\").").
    ''')
    entries = generate(task)
    assert {e.rule for e in entries} == {"p.", "q."}
    assert all(e.attributes == ('"#ilasp_script"',) for e in entries)


def test_line_comment_inside_block_comment_hides_closing_marker():
    task = parse_task('%*\n% *%\nignored.\n*%\n#maxv(0). #modeh(q).')
    assert [str(e) for e in generate(task)] == ["1 ~ q."]


def test_framing_keeps_strings_ranges_weak_annotations_and_comments():
    source = '''
        %* nested %* comment *% end *%
        #constant(t,1..2). % period . inside a comment
        #bias("attribute(\\\"a.b%\\\").").
        3 ~ :~ p(X). [1@2,X] 2 ~ q.
    '''
    assert len(statements(source)) == 4
    task = parse_task(source)
    assert task.bias == ('attribute("a.b%").',)
    assert len(task.explicit) == 2


def test_include_is_relative_and_cycles_fail(tmp_path):
    nested = tmp_path / "nested"
    nested.mkdir()
    (nested / "bias.las").write_text("#maxv(0). #modeh(p).", encoding="utf-8")
    root = tmp_path / "task.las"
    root.write_text('#include "nested/bias.las".', encoding="utf-8")
    assert [str(e) for e in generate(read_task(root))] == ["1 ~ p."]
    (nested / "bias.las").write_text('#include "../task.las".', encoding="utf-8")
    with pytest.raises(ValueError, match="cyclic"):
        read_task(root)


def test_metarule_program_is_one_selectable_unit_with_transitive_semantics():
    case = next(c for c in CASES if c["name"] == "meta_bundle")
    task = parse_task(case["source"])
    entries = generate(task)
    assert len(entries) == 1 and entries[0].cost == 5 and entries[0].meta
    program = expand_metarule(task, entries[0])
    assert len(program) == 2
    control = clingo.Control()
    control.add("base", [], "edge(a,b). edge(b,c).\n" + "\n".join(program))
    control.ground([("base", [])])
    with control.solve(yield_=True) as handle:
        models = [{str(s) for s in m.symbols(atoms=True)} for m in handle]
    assert len(models) == 1
    assert {"p1(a,b)", "p1(b,c)", "p1(a,c)"} <= models[0]


@pytest.mark.parametrize("name", ["meta_valid", "meta_choice", "meta_weak"])
def test_other_metarule_forms_expand_to_valid_asp(name):
    task = parse_task(next(c["source"] for c in CASES if c["name"] == name))
    programs = [expand_metarule(task, e) for e in generate(task)]
    assert len(programs) == 1 and len(programs[0]) == 1
    control = clingo.Control(["--warn=none"])
    control.add("base", [], "\n".join(programs[0]))
    control.ground([("base", [])])


def test_unexpandable_selector_fails_instead_of_becoming_an_empty_program():
    task = parse_task(next(c["source"] for c in CASES if c["name"] == "meta_nomatch"))
    with pytest.raises(ValueError, match="no background template"):
        expand_metarule(task, generate(task)[0])


def test_repeated_guards_and_anonymous_variables_in_metarules():
    task = parse_task(next(c["source"] for c in CASES if c["name"] == "meta_duplicate_guard"))
    assert expand_metarule(task, generate(task)[0]) == ("p1(X) :- edge(X).",)
    task = parse_task(next(c["source"] for c in CASES if c["name"] == "meta_anonymous"))
    programs = {expand_metarule(task, e) for e in generate(task)}
    assert programs == {("p1(X) :- edge(X).",), ("p1(X) :- node(X).",)}


def test_selector_dependent_rules_without_predicate_variables_are_included():
    task = parse_task('''P(X) :- Q(X), choose(P,Q). chosen :- choose(P,Q).
        #predicate(base,edge/1). #predicate(invented,p1/1).
        #modem(2,choose(invented/1,base/1)).''')
    assert expand_metarule(task, generate(task)[0]) == ("chosen.", "p1(X) :- edge(X).")


def test_zero_arity_metarule_preserves_argument_variables_and_normal_predicates():
    task = parse_task('''P :- Q, choose(P,Q). ilaspmeta_P :- choose(P,Q).
        #predicate(base,edge/0). #predicate(invented,p1/0).
        #modem(2,choose(invented/0,base/0)).''')
    entry, = generate(task)
    program = expand_metarule(task, entry)
    assert program == ("ilaspmeta_P.", "p1 :- edge.")
    control = clingo.Control()
    control.add("base", [], "edge.\n" + "\n".join(program))
    control.ground([("base", [])])
    with control.solve(yield_=True) as handle:
        models = [{str(symbol) for symbol in model.symbols(atoms=True)} for model in handle]
    assert models == [{"edge", "p1", "ilaspmeta_P"}]


def test_strict_aggregate_bounds_preserve_integer_model_semantics():
    source = "p :- 0 < #count{X:q(X)} < 2."
    entry, = generate(parse_task("0 ~ " + source))
    assert entry.cost == 0
    for background, expected in (("", False), ("q(a).", True), ("q(a). q(b).", False)):
        for rule in (source, entry.rule):
            control = clingo.Control(["--warn=none"])
            control.add("base", [], background + rule)
            control.ground([("base", [])])
            with control.solve(yield_=True) as handle:
                assert [clingo.Function("p") in model.symbols(atoms=True) for model in handle] == [expected]


@pytest.mark.parametrize("missing", ["weight", "priority"])
def test_incomplete_generated_weak_constraints_fail_without_partial_output(missing):
    fields = {"weight": "weight(1).", "priority": "priority(1)."}
    del fields[missing]
    source = '#bias("weak_body(p). ' + " ".join(fields.values()) + '").'
    with pytest.raises(ValueError, match="requires weight/1 and priority/1"):
        generate(parse_task(source), Options(override_default_sm=True))


def test_coupled_metarule_guards_fail_instead_of_removing_dependencies():
    task = parse_task('''P(X) :- edge(X), choose(P,Q), choose(P,R), active(R).
        edge(a). active(node). #predicate(base,edge/1). #predicate(invented,p1/1).
        #modem(2,choose(invented/1,base/1)).''')
    entry, = generate(task)
    with pytest.raises(ValueError, match="whole-hypothesis expansion"):
        expand_metarule(task, entry)


@pytest.mark.parametrize("background", [
    "P(X) :- Q(X), choose(P,Q), #count{0:choose(P,Q)} = 1.",
    "P(X) :- Q(X), choose(P,Q), enabled. enabled :- not choose(p1,edge).",
    "P(X) :- Q(X), choose(P,Q). choose(p1,edge).",
])
def test_hidden_or_background_selector_dependencies_are_not_silently_dropped(background):
    task = parse_task(background + ''' #predicate(base,edge/1). #predicate(invented,p1/1).
        #modem(2,choose(invented/1,base/1)).''')
    entry, = generate(task)
    with pytest.raises(ValueError, match="whole-hypothesis expansion"):
        expand_metarule(task, entry)


def test_cost_sums_custom_terms_and_attributes_are_preserved():
    task = parse_task('#maxv(0). #modeh(p). #bias("cost(2,a). cost(3,b). attribute(tag).").')
    entry, = generate(task)
    assert entry.cost == 5 and entry.attributes == ("tag",)


@pytest.mark.parametrize("source", ["#unknown(p).", "#modeb(*,q).", "#modeh(p(var(t))). garbage",
                                       "#modeb(q,(invented_option(1))).", '#bias("unterminated).', "#modeb(q;r).",
                                       "#modem."])
def test_unrecognized_or_incomplete_input_is_an_error(source):
    with pytest.raises(ValueError):
        generate(parse_task(source))


def test_cli_json_contains_complete_meta_program(tmp_path, monkeypatch, capsys):
    case = next(c for c in CASES if c["name"] == "meta_bundle")
    path = tmp_path / "meta.las"
    path.write_text(case["source"], encoding="utf-8")
    monkeypatch.setattr("sys.argv", ["ilasp-standalone", str(path), "--expand-metarules"])
    assert main() == 0
    output = json.loads(capsys.readouterr().out)
    assert len(output) == 1 and len(output[0]["program"]) == 2


def test_compiled_coin_uses_recovered_bias_semantics():
    case = next(c for c in CASES if c["name"] == "coin")
    generated = compile_task(parse_task(case["source"]))
    recovered = (Path(__file__).parents[1] / "tools/ilasp/recovered/coin-generator.lp").read_text()
    assert generated.strip() == recovered.strip()


def test_cli_native_generation_aliases_and_heuristic_encoding(tmp_path, monkeypatch, capsys):
    path = tmp_path / "task.las"
    path.write_text("#maxv(0). #modeh(p).", encoding="utf-8")
    monkeypatch.setattr("sys.argv", ["ilasp-standalone", str(path), "-st", "--version=4", "--learn-heuristics"])
    assert main() == 0
    assert "{heur}." in capsys.readouterr().out


def test_embedded_bias_python_executes_only_when_generating_and_errors_are_atomic(tmp_path, monkeypatch, capsys):
    path = tmp_path / "script.las"
    path.write_text('''0 ~ q.
        #bias("#script (python)
raise RuntimeError('intentional generator failure')
#end.
head(p).").''', encoding="utf-8")
    command = ["ilasp-standalone", str(path), "--override-default-sm"]
    monkeypatch.setattr("sys.argv", command + ["--emit-asp"])
    assert main() == 0
    assert "raise RuntimeError" in capsys.readouterr().out
    monkeypatch.setattr("sys.argv", command)
    assert main() == 1
    captured = capsys.readouterr()
    assert captured.out == ""
    assert "intentional generator failure" in captured.err
